+fn tool_call_pairing(messages: &[Value]) -> Result<(), String> {
+    let mut pending: Option<Vec<&Value>> = None;
+    let mut unpaired_ids = false;
+    for message in messages {
+        if message["role"] == "tool" {
+            if unpaired_ids {
